select throws_like($$select my_seller_statement(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,current_setting('test.otherstatement')::uuid)$$,'%STATEMENT_NOT_FOUND%','other statement denied');
select throws_ok($$select my_seller_economy(current_setting('test.tenant')::uuid,current_setting('test.other')::uuid)$$,'42501',null,'other seller denied');
select throws_ok($$select my_seller_economy(gen_random_uuid(),current_setting('test.seller')::uuid)$$,'42501',null,'other tenant denied');
select is((select count(*) from seller_ledger_entries),0::bigint,'raw ledger remains staff only');
select is((select count(*) from settlement_statements),0::bigint,'raw statements remain staff only');
