select throws_ok($$select approve_payout(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.payout')::uuid)$$,'42501',null,'seller cannot approve');
select throws_ok($$select mark_payout_paid(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.payout')::uuid,'test')$$,'42501',null,'seller cannot pay');
