select is(set_my_seller_notifications(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,current_setting('test.pref')::uuid,false),current_setting('test.pref')::uuid,'preference replay');
select throws_ok($$select set_my_seller_notifications(current_setting('test.tenant')::uuid,current_setting('test.other')::uuid,gen_random_uuid(),false)$$,'42501',null,'other preference denied');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000481","role":"authenticated"}';
select is((select request_source from payouts where id=current_setting('test.payout')::uuid),'seller','staff sees request source');
select approve_payout(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.payout')::uuid);
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000482","role":"authenticated"}';
select is((my_seller_economy(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)->'balance'->>'reservedOre')::bigint,10000::bigint,'reservation visible');
select throws_like($$select request_my_payout(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,10001)$$,'%PAYOUT_EXCEEDS_BALANCE%','reservation reduces available');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000484","role":"authenticated"}';
select throws_ok($$select my_seller_accounts()$$,'42501',null,'unverified denied');
set local role anon;
select throws_ok($$select my_seller_accounts()$$,'42501',null,'anonymous denied');
reset role;
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000481","role":"authenticated"}';
select is(allow_automatic_seller_email(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,gen_random_uuid()),false,'opt out prevents automatic transport');
select is((select detail->>'why' from access_events where tenant_id=current_setting('test.tenant')::uuid and action='seller_email.skipped' limit 1),'seller_opt_out','skip reason is persisted');
select is(allow_automatic_seller_email(current_setting('test.tenant')::uuid,current_setting('test.other')::uuid,gen_random_uuid()),true,'default permits notification subject to store policy');
