select throws_ok($$select my_seller_accounts()$$,'42501',null,'seller MFA required at SQL boundary');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000482","role":"authenticated","aal":"aal2"}';
select is(jsonb_array_length(my_seller_accounts()),1,'MFA verified seller can read');
select throws_ok($$select allow_automatic_seller_email(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,gen_random_uuid())$$,'42501',null,'seller cannot invoke staff dispatch gate');
